<div class="section-item rounded-xl border border-slate-200 bg-slate-50 p-4 space-y-3" data-item>
  <div class="flex justify-end"><button type="button" data-remove-item class="text-xs font-bold text-red-600">Remove item</button></div>
  <div class="grid gap-3 sm:grid-cols-2"><div><label class="field">Title / question / feature</label><input name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][title]" value="{{ $item['title'] ?? '' }}"></div><div><label class="field">Subtitle</label><input name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][subtitle]" value="{{ $item['subtitle'] ?? '' }}"></div><div><label class="field">Badge / timing</label><input name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][badge]" value="{{ $item['badge'] ?? '' }}"></div><div><label class="field">Value / postcodes</label><input name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][value]" value="{{ $item['value'] ?? '' }}"></div></div>
  <div><label class="field">Description / answer</label><textarea name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][description]" rows="2">{{ $item['description'] ?? '' }}</textarea></div>
  <div class="grid gap-3 sm:grid-cols-3"><div><label class="field">Icon key</label><input name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][icon]" value="{{ $item['icon'] ?? '' }}" placeholder="check, building, truck"></div><div><label class="field">Link label</label><input name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][link_label]" value="{{ $item['link_label'] ?? '' }}"></div><div><label class="field">Link URL</label><input name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][link_url]" value="{{ $item['link_url'] ?? '' }}"></div></div>
  <div class="grid gap-3 sm:grid-cols-2"><div><label class="field">Item image</label><input type="file" name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][image]" accept="image/jpeg,image/png,image/webp"><input type="hidden" name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][existing_image_path]" value="{{ $item['existing_image_path'] ?? '' }}"></div><div><label class="field">Item image alt text</label><input name="sections[{{ $sectionIndex }}][items][{{ $itemIndex }}][image_alt]" value="{{ $item['image_alt'] ?? '' }}"></div></div>
</div>
